=== FILE: apb_regs.v ===
`timescale 1ns / 1ps
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements interface_spec.md as planned in microarchitecture.md:
//   - pready tied high (zero wait states), no state machine;
//   - access = psel && penable is the completing cycle;
//   - writes take effect on the edge that ends the access phase, per strobe;
//   - mapped = word aligned and offset 0x0..0xC; otherwise pslverr;
//   - prdata and pslverr are zero outside the access phase.
module apb_regs #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output reg  [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam STRB_WIDTH = DATA_WIDTH / 8;

    // Register file: four separate flops.
    reg  [DATA_WIDTH-1:0] reg0;
    reg  [DATA_WIDTH-1:0] reg1;
    reg  [DATA_WIDTH-1:0] reg2;
    reg  [DATA_WIDTH-1:0] reg3;

    // Access phase and address decode.
    wire                  access;
    wire                  mapped;
    wire [1:0]            idx;
    wire                  wr_en;
    wire                  rd_en;
    wire                  we0;
    wire                  we1;
    wire                  we2;
    wire                  we3;

    assign access = psel & penable;
    assign mapped = (paddr[1:0] == 2'b00) &&
                    (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
    assign idx    = paddr[3:2];
    assign wr_en  = access & pwrite & mapped;
    assign rd_en  = access & ~pwrite & mapped;
    assign we0    = wr_en & (idx == 2'd0);
    assign we1    = wr_en & (idx == 2'd1);
    assign we2    = wr_en & (idx == 2'd2);
    assign we3    = wr_en & (idx == 2'd3);

    // Byte-lane write mask from pstrb: bit n enables bits 8n+7:8n.
    wire [DATA_WIDTH-1:0] wmask;
    genvar g;
    generate
        for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_wmask
            assign wmask[8*g +: 8] = {8{pstrb[g]}};
        end
    endgenerate

    // Next values: strobed bytes from pwdata, other bytes kept.
    wire [DATA_WIDTH-1:0] reg0_d;
    wire [DATA_WIDTH-1:0] reg1_d;
    wire [DATA_WIDTH-1:0] reg2_d;
    wire [DATA_WIDTH-1:0] reg3_d;

    assign reg0_d = (reg0 & ~wmask) | (pwdata & wmask);
    assign reg1_d = (reg1 & ~wmask) | (pwdata & wmask);
    assign reg2_d = (reg2 & ~wmask) | (pwdata & wmask);
    assign reg3_d = (reg3 & ~wmask) | (pwdata & wmask);

    // Register block: synchronous active-low reset, then load enables.
    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else begin
            if (we0) reg0 <= reg0_d;
            if (we1) reg1 <= reg1_d;
            if (we2) reg2 <= reg2_d;
            if (we3) reg3 <= reg3_d;
        end
    end

    // Read data: 4:1 multiplexer, zero unless a mapped read access.
    always @(*) begin
        prdata = {DATA_WIDTH{1'b0}};
        if (rd_en) begin
            case (idx)
                2'd0:    prdata = reg0;
                2'd1:    prdata = reg1;
                2'd2:    prdata = reg2;
                2'd3:    prdata = reg3;
                default: prdata = {DATA_WIDTH{1'b0}};
            endcase
        end
    end

    assign pready  = 1'b1;
    assign pslverr = access & ~mapped;

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Formal properties. Decode and byte checks are written independently
    // of the design's mapped/wmask logic.
    // ------------------------------------------------------------------
    localparam [ADDR_WIDTH-1:0] F_REG0 = 0;
    localparam [ADDR_WIDTH-1:0] F_REG1 = 4;
    localparam [ADDR_WIDTH-1:0] F_REG2 = 8;
    localparam [ADDR_WIDTH-1:0] F_REG3 = 12;

    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk)
        f_past_valid <= 1'b1;

    wire f_access;
    wire f_mapped;
    assign f_access = psel && penable;
    assign f_mapped = (paddr == F_REG0) || (paddr == F_REG1) ||
                      (paddr == F_REG2) || (paddr == F_REG3);

    reg [DATA_WIDTH-1:0] f_rdval;
    always @(*) begin
        case (paddr)
            F_REG0:  f_rdval = reg0;
            F_REG1:  f_rdval = reg1;
            F_REG2:  f_rdval = reg2;
            F_REG3:  f_rdval = reg3;
            default: f_rdval = {DATA_WIDTH{1'b0}};
        endcase
    end

    // Manager assumptions (APB rules).
    always @(*) begin
        if (!f_past_valid)
            assume(!presetn);
        if (!presetn)
            assume(!psel);
        if (penable)
            assume(psel);
    end

    always @(posedge pclk) begin
        if (f_past_valid) begin
            // An access phase follows exactly one setup phase.
            if (psel && penable)
                assume($past(psel) && !$past(penable));
            // A setup phase is followed by its access phase, with a stable request.
            if ($past(presetn) && $past(psel) && !$past(penable) && presetn) begin
                assume(psel && penable);
                assume(paddr  == $past(paddr));
                assume(pwrite == $past(pwrite));
                assume(pwdata == $past(pwdata));
                assume(pstrb  == $past(pstrb));
            end
        end
    end

    // Completer assertions.
    always @(*) begin
        assert(pready);
        if (!f_access) begin
            assert(prdata == {DATA_WIDTH{1'b0}});
            assert(!pslverr);
        end else begin
            assert(pslverr == !f_mapped);
            if (pwrite || !f_mapped)
                assert(prdata == {DATA_WIDTH{1'b0}});
            else
                assert(prdata == f_rdval);
        end
    end

    // Registers are zero after reset.
    always @(posedge pclk) begin
        if (f_past_valid && !$past(presetn)) begin
            assert(reg0 == {DATA_WIDTH{1'b0}});
            assert(reg1 == {DATA_WIDTH{1'b0}});
            assert(reg2 == {DATA_WIDTH{1'b0}});
            assert(reg3 == {DATA_WIDTH{1'b0}});
        end
    end

    // Each byte of each register changes only in a mapped write access to
    // that register with its strobe set, and then to the written byte.
    wire [4*DATA_WIDTH-1:0] f_regs;
    assign f_regs = {reg3, reg2, reg1, reg0};

    genvar fr;
    genvar fb;
    generate
        for (fr = 0; fr < 4; fr = fr + 1) begin : g_f_reg
            for (fb = 0; fb < STRB_WIDTH; fb = fb + 1) begin : g_f_byte
                always @(posedge pclk) begin
                    if (f_past_valid && $past(presetn)) begin
                        if ($past(psel && penable && pwrite) &&
                            ($past(paddr) == fr * 4) && $past(pstrb[fb]))
                            assert(f_regs[fr*DATA_WIDTH + 8*fb +: 8] ==
                                   $past(pwdata[8*fb +: 8]));
                        else
                            assert(f_regs[fr*DATA_WIDTH + 8*fb +: 8] ==
                                   $past(f_regs[fr*DATA_WIDTH + 8*fb +: 8]));
                    end
                end
            end
        end
    endgenerate

    // Covers: the behaviour the spec promises is reachable.
    always @(posedge pclk) begin
        if (f_past_valid && $past(presetn) && presetn) begin
            cover(f_access && pwrite && f_mapped && (pstrb == {STRB_WIDTH{1'b1}}));
            cover(f_access && pwrite && f_mapped && (pstrb == {STRB_WIDTH{1'b0}}));
            cover(f_access && !pwrite && (paddr == F_REG3) && (prdata == 32'hA5C3_0F96));
            cover(f_access && !pwrite && (paddr == F_REG0) && (prdata == 32'h1234_5678));
            cover(f_access && pwrite && !f_mapped);
            cover(f_access && !pwrite && !f_mapped);
        end
    end
`endif

endmodule
=== END FILE ===
=== FILE: apb_regs_tb.v ===
`timescale 1ns / 1ps

// Every check goes through NCHECK: a pass is counted, a failure is counted
// and reported with $error.
`define NCHECK(cond, msg) \
    begin \
        if (cond) begin \
            passed = passed + 1; \
        end else begin \
            failed = failed + 1; \
            $error msg; \
        end \
    end

module apb_regs_tb;

    reg         pclk = 1'b0;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    integer        passed;
    integer        failed;
    reg [8*64-1:0] nonce;

    // Expected register contents, computed from the stimulus.
    reg [31:0] model [0:3];

    integer    r;
    integer    i;
    reg [7:0]  addr_v;
    reg [31:0] data_v;

    apb_regs #(
        .ADDR_WIDTH(8),
        .DATA_WIDTH(32)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    always #5 pclk = ~pclk;

    // Independent decode: mapped only at the four aligned offsets.
    function tb_mapped;
        input [7:0] a;
        begin
            tb_mapped = (a == 8'h00) || (a == 8'h04) || (a == 8'h08) || (a == 8'h0C);
        end
    endfunction

    function [31:0] exp_read;
        input [7:0] a;
        begin
            case (a)
                8'h00:   exp_read = model[0];
                8'h04:   exp_read = model[1];
                8'h08:   exp_read = model[2];
                8'h0C:   exp_read = model[3];
                default: exp_read = 32'h0000_0000;
            endcase
        end
    endfunction

    task model_write;
        input [7:0]  a;
        input [31:0] d;
        input [3:0]  s;
        reg   [31:0] cur;
        begin
            if (tb_mapped(a)) begin
                cur = model[a[3:2]];
                if (s[0]) cur[7:0]   = d[7:0];
                if (s[1]) cur[15:8]  = d[15:8];
                if (s[2]) cur[23:16] = d[23:16];
                if (s[3]) cur[31:24] = d[31:24];
                model[a[3:2]] = cur;
            end
        end
    endtask

    task check_quiet;
        begin
            `NCHECK(prdata === 32'h0000_0000, ("t=%0t: prdata 0x%h outside the access phase, expected 0", $time, prdata))
            `NCHECK(pslverr === 1'b0, ("t=%0t: pslverr %b outside the access phase, expected 0", $time, pslverr))
        end
    endtask

    task check_regs;
        reg [127:0] got_r;
        reg [127:0] exp_r;
        begin
            got_r = {dut.reg3, dut.reg2, dut.reg1, dut.reg0};
            exp_r = {model[3], model[2], model[1], model[0]};
            `NCHECK(got_r === exp_r, ("t=%0t: registers (reg3..reg0) 0x%h, expected 0x%h", $time, got_r, exp_r))
        end
    endtask

    // Reset for n checked cycles with psel low, then release.
    task do_reset;
        input integer n;
        integer j;
        begin
            @(negedge pclk);
            presetn = 1'b0;
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = 8'h00;
            pwdata  = 32'hFFFF_FFFF;
            pstrb   = 4'hF;
            @(posedge pclk);
            model[0] = 32'h0000_0000;
            model[1] = 32'h0000_0000;
            model[2] = 32'h0000_0000;
            model[3] = 32'h0000_0000;
            for (j = 0; j < n; j = j + 1) begin
                @(negedge pclk);
                #2;
                check_quiet;
                check_regs;
            end
            @(negedge pclk);
            presetn = 1'b1;
            #2;
            check_quiet;
            check_regs;
        end
    endtask

    // n idle cycles with distracting inputs: psel low, so nothing may happen.
    task idle;
        input integer n;
        integer j;
        begin
            for (j = 0; j < n; j = j + 1) begin
                @(negedge pclk);
                psel    = 1'b0;
                penable = 1'b0;
                pwrite  = j[0];
                paddr   = 8'h04;
                pwdata  = 32'hA5A5_A5A5;
                pstrb   = 4'hF;
                #2;
                check_quiet;
                check_regs;
            end
        end
    endtask

    task apb_write;
        input [7:0]  a;
        input [31:0] d;
        input [3:0]  s;
        reg          exp_err;
        begin
            exp_err = !tb_mapped(a);
            // Setup phase
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = a;
            pwdata  = d;
            pstrb   = s;
            #2;
            check_quiet;
            // Access phase
            @(negedge pclk);
            penable = 1'b1;
            #2;
            `NCHECK(pready === 1'b1, ("t=%0t: write 0x%h: pready %b in the access phase, expected 1 (zero wait states)", $time, a, pready))
            `NCHECK(pslverr === exp_err, ("t=%0t: write 0x%h: pslverr %b, expected %b", $time, a, pslverr, exp_err))
            `NCHECK(prdata === 32'h0000_0000, ("t=%0t: write 0x%h: prdata 0x%h in a write access, expected 0", $time, a, prdata))
            // Nothing may have changed at the setup edge.
            check_regs;
            @(posedge pclk);
            #1;
            model_write(a, d, s);
            check_regs;
        end
    endtask

    task apb_read;
        input [7:0]  a;
        reg          exp_err;
        reg   [31:0] exp_d;
        begin
            exp_err = !tb_mapped(a);
            exp_d   = exp_read(a);
            // Setup phase
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = a;
            pwdata  = 32'hFFFF_FFFF;
            pstrb   = 4'h0;
            #2;
            check_quiet;
            // Access phase
            @(negedge pclk);
            penable = 1'b1;
            #2;
            `NCHECK(pready === 1'b1, ("t=%0t: read 0x%h: pready %b in the access phase, expected 1 (zero wait states)", $time, a, pready))
            `NCHECK(pslverr === exp_err, ("t=%0t: read 0x%h: pslverr %b, expected %b", $time, a, pslverr, exp_err))
            `NCHECK(prdata === exp_d, ("t=%0t: read 0x%h: prdata 0x%h, expected 0x%h", $time, a, prdata, exp_d))
            @(posedge pclk);
            #1;
            check_regs;
        end
    endtask

    task finish_run;
        begin
            if (!$value$plusargs("nirmaan_nonce=%s", nonce))
                nonce = {(8*64){1'b0}};
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    endtask

    initial begin
        passed   = 0;
        failed   = 0;
        nonce    = {(8*64){1'b0}};
        presetn  = 1'b0;
        psel     = 1'b0;
        penable  = 1'b0;
        pwrite   = 1'b0;
        paddr    = 8'h00;
        pwdata   = 32'h0000_0000;
        pstrb    = 4'h0;
        model[0] = 32'h0000_0000;
        model[1] = 32'h0000_0000;
        model[2] = 32'h0000_0000;
        model[3] = 32'h0000_0000;

        // 1. Reset values.
        do_reset(3);
        idle(2);
        apb_read(8'h00);
        apb_read(8'h04);
        apb_read(8'h08);
        apb_read(8'h0C);
        idle(1);

        // 2. Full-word writes back to back, an idle gap, then readback.
        apb_write(8'h00, 32'h0123_4567, 4'hF);
        apb_write(8'h04, 32'h89AB_CDEF, 4'hF);
        apb_write(8'h08, 32'hDEAD_BEEF, 4'hF);
        apb_write(8'h0C, 32'hC0FF_EE11, 4'hF);
        idle(3);
        apb_read(8'h00);
        apb_read(8'h04);
        apb_read(8'h08);
        apb_read(8'h0C);
        idle(1);

        // 3. Interleaved back-to-back writes and reads.
        apb_write(8'h08, 32'h1357_9BDF, 4'hF);
        apb_read(8'h08);
        apb_write(8'h0C, 32'h2468_ACE0, 4'hF);
        apb_read(8'h0C);
        apb_read(8'h00);
        idle(2);

        // 4. Every strobe pattern on every register; each write inverts the
        //    old value so every strobed lane changes and others must not.
        for (r = 0; r < 4; r = r + 1) begin
            for (i = 0; i < 16; i = i + 1) begin
                addr_v = {4'h0, r[1:0], 2'b00};
                data_v = ~exp_read(addr_v);
                apb_write(addr_v, data_v, i[3:0]);
                apb_read(addr_v);
            end
            idle(1);
        end

        // 5. Zero strobe: no change, no error.
        apb_write(8'h04, 32'hFFFF_FFFF, 4'h0);
        apb_read(8'h04);
        idle(1);

        // 6. PSLVERR policy over the whole slot. Known values first.
        apb_write(8'h00, 32'h1111_1111, 4'hF);
        apb_write(8'h04, 32'h2222_2222, 4'hF);
        apb_write(8'h08, 32'h3333_3333, 4'hF);
        apb_write(8'h0C, 32'h4444_4444, 4'hF);
        for (i = 0; i < 256; i = i + 1) begin
            addr_v = i[7:0];
            if (!tb_mapped(addr_v))
                apb_write(addr_v, 32'hBAD0_0000 | {24'h00_0000, addr_v}, 4'hF);
            apb_read(addr_v);
            if ((i % 16) == 15)
                idle(1);
        end
        apb_read(8'h00);
        apb_read(8'h04);
        apb_read(8'h08);
        apb_read(8'h0C);

        // 7. Reset again, then the block still works.
        do_reset(2);
        apb_read(8'h00);
        apb_read(8'h04);
        apb_read(8'h08);
        apb_read(8'h0C);
        apb_write(8'h0C, 32'hFACE_B00C, 4'h3);
        apb_read(8'h0C);
        apb_write(8'h00, 32'h1234_5678, 4'hF);
        apb_read(8'h00);
        idle(2);

        finish_run;
    end

    // Watchdog: a hung run still ends with a failing verdict.
    initial begin
        #1000000;
        failed = failed + 1;
        $error("watchdog: simulation did not finish in time");
        finish_run;
    end

